(function(){'use strict';
const SC=window.StorageSchema,EN=window.StorageEngine,stores=['datasets','tables','runs','run-meta'],memory=Object.fromEntries(stores.map(k=>[k,new Map()]));let temporary=false;
const prefsCache=new Map();window.workspacePrefs={getItem(k){try{return localStorage.getItem(k);}catch{return prefsCache.get(k)||null;}},setItem(k,v){try{localStorage.setItem(k,v);}catch{prefsCache.set(k,v);}}};
const ready=new Promise(resolve=>{try{const r=indexedDB.open('public-storage-planning-workspace-v1',1);r.onupgradeneeded=()=>{for(const s of stores)if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>{temporary=true;resolve(null);};}catch{temporary=true;resolve(null);}});
async function dbOp(store,method,arg){const db=await ready;if(!db){const m=memory[store];if(method==='get')return m.get(arg);if(method==='getAll')return Array.from(m.values());if(method==='put'){m.set(arg.id,arg);return arg.id;}}
 return new Promise((resolve,reject)=>{const tx=db.transaction(store,method==='put'?'readwrite':'readonly'),s=tx.objectStore(store);let result;const r=method==='getAll'?s.getAll():s[method](arg);r.onsuccess=()=>{result=r.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('浏览器无法保存数据，请检查存储权限或导出现有结果后清理空间。'));tx.onabort=tx.onerror;});}
const uid=()=>crypto.randomUUID().replace(/-/g,'').slice(0,12),normal=s=>String(s).trim().replace(/\s/g,'').toLowerCase();
const fields=[...SC.features,...SC.outputs];
function suggest(columns){const lookup=new Map(columns.map(c=>[normal(c),c]));return Object.fromEntries(fields.map(f=>[f.key,(f.aliases||[f.key]).map(a=>lookup.get(normal(a))).find(Boolean)||'']));}
function makeTable(records){if(!records.length)throw Error('工作表为空。');const candidates=records.slice(0,10),scores=candidates.map(r=>Object.values(suggest(r.cells.filter(v=>v!=null))).filter(Boolean).length),h=scores.indexOf(Math.max(...scores));const width=Math.max(...records.map(r=>r.cells.length));if(width>150)throw Error('每张表最多支持150列。');const used=new Set(),columns=Array.from({length:width},(_,j)=>{let k=String(records[h].cells[j]??'_空列'+(j+1)).trim()||'_空列'+(j+1);if(used.has(k))k+='_'+(j+1);used.add(k);return k;});const rows=records.slice(h+1).filter(r=>r.cells.some(v=>v!=null&&v!=='')).map(r=>({source_row:r.source_row,cells:Array.from({length:width},(_,j)=>r.cells[j]??null)}));return {columns,rows,header_row:records[h].source_row};}
function parseCSV(text){const matrix=[],row=[];let cell='',quoted=false;const flushCell=()=>{row.push(cell);cell='';if(row.length>150)throw Error('CSV最多支持150列。');};const flushRow=()=>{flushCell();matrix.push({source_row:matrix.length+1,cells:row.splice(0)});if(matrix.length>30000)throw Error('CSV最多支持30000行。');};text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"'&&!cell)quoted=true;else if(c===',')flushCell();else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;flushRow();}else cell+=c;}if(quoted)throw Error('CSV引号未闭合。');if(cell||row.length)flushRow();return makeTable(matrix);}
function zipLimit(buffer){const b=new DataView(buffer);let p=buffer.byteLength-22;while(p>=Math.max(0,buffer.byteLength-65557)&&b.getUint32(p,true)!==0x06054b50)p--;if(p<0)throw Error('Excel压缩包结构无效。');let q=b.getUint32(p+16,true),size=0;const count=b.getUint16(p+10,true);if(count===65535||q===4294967295)throw Error('不支持超大型ZIP64工作簿。');for(let i=0;i<count;i++){if(q+46>buffer.byteLength||b.getUint32(q,true)!==0x02014b50)throw Error('工作簿压缩目录无效。');size+=b.getUint32(q+24,true);if(size>96*1024*1024)throw Error('解压后的工作簿不能超过96MB，请拆分数据。');q+=46+b.getUint16(q+28,true)+b.getUint16(q+30,true)+b.getUint16(q+32,true);}}
function normalizedPath(p){const out=[];for(const x of p.split('/'))if(x==='..')out.pop();else if(x&&x!=='.')out.push(x);return out.join('/');}
async function parseXLSX(buffer){zipLimit(buffer);const zip=await JSZip.loadAsync(buffer);let readSize=0;async function xml(path){const f=zip.file(path);if(!f)throw Error('工作簿缺少必要文件：'+path);const s=await f.async('string');readSize+=s.length;if(readSize>96*1024*1024)throw Error('工作簿内容过大。');if(/<!DOCTYPE|<!ENTITY/i.test(s))throw Error('不支持包含外部实体的XML。');const doc=new DOMParser().parseFromString(s,'application/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('Excel XML无法解析。');return doc;}
 const all=(node,name)=>Array.from(node.getElementsByTagNameNS('*',name)),book=await xml('xl/workbook.xml'),rels=await xml('xl/_rels/workbook.xml.rels'),targets=new Map(all(rels,'Relationship').filter(r=>r.getAttribute('TargetMode')!=='External').map(r=>[r.getAttribute('Id'),normalizedPath((r.getAttribute('Target')||'').startsWith('/')?r.getAttribute('Target'):'xl/'+r.getAttribute('Target'))]));let strings=[];if(zip.file('xl/sharedStrings.xml'))strings=all(await xml('xl/sharedStrings.xml'),'si').map(n=>all(n,'t').map(t=>t.textContent).join(''));
 const tables=Object.create(null);for(const s of all(book,'sheet')){const name=s.getAttribute('name'),id=s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||s.getAttribute('r:id'),path=targets.get(id);if(!path)continue;const doc=await xml(path),records=[];let previous=0;for(const row of all(doc,'row')){const source=Number(row.getAttribute('r'))||previous+1;previous=source;if(source>30000)throw Error('每张工作表最多支持30000行。');const cells=[];let col=0;for(const c of all(row,'c')){const ref=(c.getAttribute('r')||'').match(/^[A-Z]+/i);if(ref){col=0;for(const ch of ref[0].toUpperCase())col=col*26+ch.charCodeAt(0)-64;col--;}if(col>=150)throw Error('每张工作表最多支持150列。');const type=c.getAttribute('t'),v=all(c,'v')[0]?.textContent;let value=null;if(type==='s')value=strings[Number(v)]??null;else if(type==='inlineStr')value=all(c,'t').map(t=>t.textContent).join('');else if(type==='str')value=v??null;else if(type==='b')value=v==='1';else if(type==='e')value=null;else if(v!=null&&v!=='')value=Number.isFinite(Number(v))?Number(v):v;cells[col]=value;col++;}if(cells.some(v=>v!=null&&v!==''))records.push({source_row:source,cells});}if(records.length)tables[name]=makeTable(records);}
 if(!Object.keys(tables).length)throw Error('没有可读取的工作表。');return tables;}
async function sha(buffer){const h=await crypto.subtle.digest('SHA-256',buffer);return Array.from(new Uint8Array(h),b=>b.toString(16).padStart(2,'0')).join('');}
function stats(table){const mapping=suggest(table.columns),column_stats={};table.columns.forEach((col,j)=>{const ns=table.rows.map(r=>EN.numeric(r.cells[j])).filter(Number.isFinite);if(ns.length)column_stats[col]={column:col,valid:ns.length,missing:table.rows.length-ns.length,unique:new Set(ns).size,min:Math.min(...ns),max:Math.max(...ns)};});return {rows:table.rows.length,columns:table.columns,header_row:table.header_row,mapping,column_stats,stats:Object.fromEntries(Object.entries(mapping).filter(([k,v])=>column_stats[v]).map(([k,v])=>[k,column_stats[v]])),preview:table.rows.slice(0,8).map(r=>Object.fromEntries(table.columns.map((c,j)=>[c,r.cells[j]]))),missing_features:SC.features.filter(f=>!mapping[f.key]).map(f=>f.key),feature_count:SC.features.filter(f=>mapping[f.key]).length,output_count:SC.outputs.filter(f=>mapping[f.key]).length};}
async function saveDataset(name,tables,hash,synthetic,example=false){const existing=(await dbOp('datasets','getAll')).find(d=>d.sha256===hash);if(existing)return existing;const sheets=Object.keys(tables),scored=sheets.map(s=>({s,n:Object.values(suggest(tables[s].columns)).filter(Boolean).length})).sort((a,b)=>b.n-a.n);const meta={id:uid(),name,sheets,default_sheet:scored[0].s,sha256:hash,example,synthetic_demo:synthetic,data_notice:synthetic?'合成演示数据：由独立示例公式生成，供功能验证使用；SHAP解释示例规则，不是实际规划优化求解结果。':'',created_at:new Date().toISOString()};await dbOp('tables','put',{id:meta.id,tables});await dbOp('datasets','put',meta);return meta;}
async function demo(){const table=EN.makeDemo(SC),name='公开合成示例2400组.csv',hash=await sha(new TextEncoder().encode(JSON.stringify(table)));return saveDataset(name,{'完整映射2400组':table},hash,true,true);}
async function importFile(file){if(!file||!file.name)throw Error('请选择数据文件。');if(file.size>32*1024*1024)throw Error('文件不能超过32MB。');const buffer=await file.arrayBuffer();let tables;if(/\.xlsx$/i.test(file.name))tables=await parseXLSX(buffer);else if(/\.csv$/i.test(file.name)){let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(buffer);}catch{text=new TextDecoder('gb18030').decode(buffer);}tables={'CSV数据':parseCSV(text)};}else throw Error('仅支持.xlsx和.csv格式。');let synthetic=/合成|synthetic|demo/i.test(file.name);for(const t of Object.values(tables)){const j=t.columns.indexOf('Data_origin');if(j>=0&&t.rows.some(r=>/SYNTHETIC_DEMO/i.test(String(r.cells[j]))))synthetic=true;}return saveDataset(file.name,tables,await sha(buffer),synthetic);}
async function datasetAndTable(id,sheet){const meta=await dbOp('datasets','get',id);if(!meta)throw Error('本浏览器工作区中没有该数据集。');sheet=sheet||meta.default_sheet;if(!meta.sheets.includes(sheet))throw Error('工作表不存在。');const record=await dbOp('tables','get',id);return {meta,table:record.tables[sheet],sheet};}
const jobs=new Map();let running=null;
async function start(config){if(running)throw Error('当前浏览器正在分析，请等待完成。');const {meta,table,sheet}=await datasetAndTable(config.dataset_id,config.sheet),id=uid(),job={id,status:'queued',progress:0,logs:[]};config={...config,sheet};jobs.set(id,job);running=id;const worker=new Worker('/static/analysis-worker.js');
 const fail=message=>{job.status='error';job.error=message;job.logs.push({title:'分析未完成',detail:message,time:new Date().toLocaleTimeString('zh-CN')});running=null;worker.terminate();};
 worker.onerror=e=>fail('计算线程发生错误：'+(e.message||'请刷新页面后重试。'));
 worker.onmessage=async e=>{const m=e.data;if(m.type==='progress'){job.status='running';job.progress=Math.round(m.progress);const log={title:m.title,detail:m.detail,time:new Date().toLocaleTimeString('zh-CN')};if(job.logs.at(-1)?.title===m.title)job.logs[job.logs.length-1]=log;else job.logs.push(log);}else if(m.type==='error')fail(m.error);else if(m.type==='done'){try{const r=m.result;await dbOp('runs','put',r);await dbOp('run-meta','put',Object.fromEntries(['id','created_at','dataset_name','sheet','duration_seconds'].map(k=>[k,r[k]])));job.status='done';job.progress=100;job.logs.push({title:'分析完成',detail:'已校验SHAP加和，并保存到当前浏览器。',time:new Date().toLocaleTimeString('zh-CN')});running=null;worker.terminate();}catch(err){fail(err.message);}}};worker.postMessage({id,table,config,meta});return {id};}
async function getRun(id){const r=await dbOp('runs','get',id);if(!r)throw Error('当前浏览器没有该分析记录，请先导入数据并运行分析。');return r;}
async function api(path,options={}){await ready;const u=new URL(path,location.href),p=u.pathname,method=options.method||'GET';let data={};if(typeof options.body==='string')data=JSON.parse(options.body);if(p==='/api/catalog')return SC;if(p==='/api/health')return {app:'storage-shap-public',status:'ok',local_only:true};if(p==='/api/datasets'&&method==='GET')return (await dbOp('datasets','getAll')).sort((a,b)=>a.created_at.localeCompare(b.created_at));if(p==='/api/datasets/example')return demo();if(p==='/api/datasets/upload')return importFile(options.body.get('file'));let m=p.match(/^\/api\/datasets\/([a-f0-9]{12})\/(inspect|stages)$/);if(m){const {meta,table,sheet}=await datasetAndTable(m[1],u.searchParams.get('sheet'));if(m[2]==='inspect')return {...stats(table),sheet,dataset:meta};const j=table.columns.indexOf(u.searchParams.get('column'));return j<0?[]:Array.from(new Set(table.rows.map(r=>r.cells[j]).filter(v=>v!=null&&v!=='').map(String))).sort();}if(p==='/api/runs'&&method==='POST')return start(data);if(p==='/api/runs')return (await dbOp('run-meta','getAll')).sort((a,b)=>b.created_at.localeCompare(a.created_at));m=p.match(/^\/api\/jobs\/([a-f0-9]{12})$/);if(m){if(jobs.has(m[1]))return structuredClone(jobs.get(m[1]));await getRun(m[1]);return {id:m[1],status:'done',progress:100,logs:[]};}m=p.match(/^\/api\/runs\/([a-f0-9]{12})$/);if(m)return getRun(m[1]);throw Error('浏览器工作区不支持该操作。');}
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function csv(matrix){return '\uFEFF'+matrix.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function report(r){const defs=[],sections=[];for(const [key,t] of Object.entries(r.targets)){const order=r.features.map((f,j)=>j).sort((a,b)=>t.importance_test[a]-t.importance_test[b]),labels=order.map(j=>r.features[j].label),ix=r.test_indices;const add=(suffix,title,traces,layout={})=>{const id=key+suffix;sections.push('<section><h2>'+escape(t.label)+' · '+title+'</h2><div id="'+id+'" style="height:470px"></div></section>');defs.push({id,data:traces,layout:{margin:{l:280,r:70,t:25,b:70},font:{family:'Microsoft YaHei,Arial',size:11},...layout}});};
 add('importance','关键因素排序',[{type:'bar',orientation:'h',y:labels,x:order.map(j=>t.importance_test[j]),marker:{color:'#315def'}}],{xaxis:{title:'mean(|SHAP|) / '+t.unit}});
 const traces=order.map((j,pos)=>{const v=ix.map(i=>r.rows[i].features[r.features[j].key]),lo=Math.min(...v),hi=Math.max(...v);return {type:'scatter',mode:'markers',x:ix.map(i=>t.shap[i][j]),y:ix.map((i,k)=>pos+((k*37%17)/17-.5)*.5),showlegend:false,marker:{size:4,opacity:.7,color:v.map(a=>(a-lo)/(hi-lo||1)),cmin:0,cmax:1,colorscale:[[0,'#2899c5'],[1,'#ef5689']],showscale:pos===0,colorbar:{title:'特征值',tickvals:[0,1],ticktext:['低','高']}}};});add('beeswarm','SHAP分布',traces,{xaxis:{title:'SHAP / '+t.unit},yaxis:{tickvals:order.map((_,i)=>i),ticktext:labels}});
 const j=order.at(-1);add('dependence','首要因素依赖',[{type:'scatter',mode:'markers',x:ix.map(i=>r.rows[i].features[r.features[j].key]),y:ix.map(i=>t.shap[i][j]),marker:{size:5,color:'#189c9a',opacity:.7}}],{margin:{l:90,r:35,t:25,b:75},xaxis:{title:r.features[j].label},yaxis:{title:'SHAP / '+t.unit}});
 const sorted=[...ix].sort((a,b)=>t.predicted[a]-t.predicted[b]),subset=sorted.filter((_,k)=>k%Math.max(1,Math.ceil(ix.length/200))===0);add('heatmap','贡献热力图',[{type:'heatmap',x:subset.map(i=>r.rows[i].id),y:labels,z:order.map(j=>subset.map(i=>t.shap[i][j])),zmid:0,colorscale:[[0,'#2899c5'],[.5,'#fff'],[1,'#ef5689']]}],{xaxis:{showticklabels:false,title:'按预测值升序排列的样本'}});
 const i=ix[0],local=order.slice().sort((a,b)=>Math.abs(t.shap[i][b])-Math.abs(t.shap[i][a]));add('waterfall','局部解释 '+r.rows[i].id,[{type:'waterfall',orientation:'h',measure:['absolute',...local.map(()=>'relative'),'total'],x:[t.base_value,...local.map(j=>t.shap[i][j]),0],y:['基准',...local.map(j=>r.features[j].label),'模型预测'],increasing:{marker:{color:'#ef5689'}},decreasing:{marker:{color:'#189c9a'}}}],{yaxis:{autorange:'reversed'},xaxis:{title:t.unit}});
 add('fit','独立测试集评估',[{type:'scatter',mode:'markers',x:ix.map(i=>t.actual[i]),y:ix.map(i=>t.predicted[i]),marker:{size:4,color:'#315def'}}],{margin:{l:90,r:35,t:25,b:65},xaxis:{title:'实际值 / '+t.unit},yaxis:{title:'预测值 / '+t.unit}});
 }
 const payload=JSON.stringify(defs).replace(/</g,'\\u003c');return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>储能规划SHAP分析报告</title><style>body{font-family:Microsoft YaHei,Arial;background:#f2f7ff;color:#142b4c;max-width:1280px;margin:32px auto;padding:0 15px;line-height:1.8}section{background:#fff;border:1px solid #bed6f7;border-radius:7px;padding:20px;margin:18px 0}h1{font-size:25px}.notice{padding:13px;background:#fff8e9}p,li{font-size:13px}</style><h1>多时间尺度储能协同规划可解释分析</h1><p>'+escape(r.dataset_name)+' · '+escape(r.sheet)+' · '+escape(r.created_at)+'</p><p>有效记录 '+r.rows.length+'，训练 '+r.train_indices.length+'，测试 '+r.test_indices.length+'；'+escape(r.method)+'。</p><p class="notice">'+escape(r.data_notice||r.explanation_boundary)+'</p><p>'+escape(r.emission_note)+'</p><ul>'+r.warnings.map(w=>'<li>'+escape(w)+'</li>').join('')+'</ul>'+Object.values(r.targets).map(t=>'<p>'+escape(t.label)+'：测试 R²='+escape(t.test_metrics.r2)+'，MAE='+escape(t.test_metrics.mae)+' '+escape(t.unit)+'，SHAP加和误差='+escape(t.additivity_max_error)+'</p>').join('')+sections.join('')+'<script>'+window.PUBLIC_PLOTLY_SOURCE+'</script><script>const figures='+payload+';for(const f of figures)Plotly.newPlot(f.id,f.data,f.layout,{responsive:true,displaylogo:false});</script></html>';
}
let plotlySource;async function loadPlotlySource(){if(!plotlySource)plotlySource=fetch('/static/vendor/plotly.min.js').then(r=>{if(!r.ok)throw Error('图表库未能加载，请刷新后重新导出。');return r.text();});window.PUBLIC_PLOTLY_SOURCE=await plotlySource;}
async function exportData(kind,id){if(kind==='template'){download(new Blob([csv([fields.map(f=>f.key)])],{type:'text/csv;charset=utf-8'}),'储能规划输入输出模板.csv');return;}const r=await getRun(id);await loadPlotlySource();const html=report(r);if(kind==='report'){download(new Blob([html],{type:'text/html;charset=utf-8'}),'储能规划-SHAP分析报告.html');return;}const z=new JSZip();z.file('analysis.json',JSON.stringify(r,null,2));z.file('report.html',html);const origin=r.synthetic_demo?'SYNTHETIC_DEMO':'USER_IMPORTED_DATA';for(const [k,t] of Object.entries(r.targets)){z.file(k+'-SHAP.csv',csv([['方案','原表行号','样本分组','实际值','预测值','基准值',...r.features.map(f=>f.label),'Data_origin'],...r.rows.map((row,i)=>[row.id,row.source_row,row.split,t.actual[i],t.predicted[i],t.base_value,...t.shap[i],origin])]));z.file(k+'-因素排序.csv',csv([['因素','测试集平均绝对SHAP','全样本平均绝对SHAP'],...r.features.map((f,j)=>[f.label,t.importance_test[j],t.importance_all[j]])]));}z.file('README.txt',(r.data_notice||'用户自主导入数据。')+'\nTree SHAP解释模型预测，不代表因果效应。数据与计算独立保存在当前浏览器，服务器未接收本次文件。report.html可离线打开。');download(await z.generateAsync({type:'blob',compression:'DEFLATE'}),'储能规划-SHAP完整分析.zip');}
window.localReady=ready;window.storageCloudApi=api;window.localExports=exportData;window.forceUrl=(id,target,sample)=>'/force.html#'+new URLSearchParams({id,target,sample}).toString();window.SiteData={getRun,listDatasets:()=>dbOp('datasets','getAll'),isTemporary:()=>temporary,parseCSV,parseXLSX};
})();
